  "claim": {
    "component_id": "C014",
    "value": "Where available, exports should be compared with others similar in workspace size, object count, execution window and worker version.",
    "scope": "Conditional on comparable cases being available; the mapping supplies no matching tolerances.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies all four comparison dimensions and the availability condition."
    }
  },
  "signal_basis": {
    "component_id": "C014_SIGNAL",
    "value": "A version association may persist within comparable workloads and execution windows or disappear after accounting for coverage or workload. Version, workload and overnight load can confound comparisons.",
    "scope": "Proposed comparative observations, assumed to occur for this judgment; their interpretation remains subject to coverage and measurement limitations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans describe the comparative signal, its confounding and measurement qualifications, and its proposed status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C014_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without a separate unresolved empirical relation."
    }
  },
  "rationale": "Comparing available exports with similar workload, timing and worker characteristics is warranted for assessing competing explanations while reducing obvious alternative explanations for observed differences. The claim prescribes a comparison strategy; it does not assert that these dimensions ensure exchangeability or identify a cause. Unspecified matching tolerances do not defeat this limited recommendation.",
  "uncertainty": "The mapping does not establish how similar cases must be or how much confounding remains; neither is asserted by this claim.",
  "anomalies": []
}
